import{_ as t,o,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const l="/docs/images/sheets/conditional-formatting-rules.png",p=JSON.parse('{"title":"Highlight cells with conditional formatting","description":"Color, bold, or underline cells automatically when their values match a rule.","frontmatter":{"title":"Highlight cells with conditional formatting","description":"Color, bold, or underline cells automatically when their values match a rule.","type":"how-to"},"headers":[],"relativePath":"sheets/conditional-formatting.md","filePath":"sheets/conditional-formatting.md"}'),n={name:"sheets/conditional-formatting.md"};function i(s,e,d,h,c,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="highlight-cells-with-conditional-formatting" tabindex="-1">Highlight cells with conditional formatting <a class="header-anchor" href="#highlight-cells-with-conditional-formatting" aria-label="Permalink to &quot;Highlight cells with conditional formatting&quot;">​</a></h1><p>Color, bold, or underline cells automatically when their values match a rule.</p><p>A rule never changes the cell&#39;s value or the formatting you applied by hand. Delete the rule and the cells look as they did before.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. Viewers and share-link visitors see the formatting but can&#39;t open the panel.</li><li>Rules belong to one tab and work on sheet and pivot tabs.</li></ul></div><h2 id="add-a-rule" tabindex="-1">Add a rule <a class="header-anchor" href="#add-a-rule" aria-label="Permalink to &quot;Add a rule&quot;">​</a></h2><ol><li>Open the sheet and select the cells to format, for example <strong>B2:B50</strong>.</li><li>Click <strong>Conditional formatting</strong> (the palette icon) in the toolbar.</li><li>The panel opens on a new, <strong>Unsaved</strong> rule for your selection. It starts as <strong>Is not empty</strong> with a light green fill and black text.</li><li>Under <strong>Format rules</strong>, pick a condition and enter its value, for example <strong>Greater than</strong> <code>1000</code>.</li><li>Under <strong>Formatting style</strong>, set <strong>Bold</strong>, <strong>Italic</strong>, <strong>Underline</strong>, <strong>Text color</strong>, or <strong>Background color</strong>.</li><li>Click <strong>Done</strong>.</li></ol><p>Matching cells take the style right away. To discard the rule instead, click <strong>Cancel</strong> or close the panel.</p><p><img src="'+l+'" alt="Conditional formatting panel with two numbered rules: green fill over 1000, yellow fill from 500 to 1000"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap <strong>More formatting options</strong> (⋮) at the right end of the toolbar, then select <strong>Conditional formatting</strong>.</p><h3 id="add-another-rule" tabindex="-1">Add another rule <a class="header-anchor" href="#add-another-rule" aria-label="Permalink to &quot;Add another rule&quot;">​</a></h3><p>Click <strong>Add</strong> in the panel. A new rule appears for the current selection and saves as you edit it.</p><h2 id="choose-a-condition" tabindex="-1">Choose a condition <a class="header-anchor" href="#choose-a-condition" aria-label="Permalink to &quot;Choose a condition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Matches a cell that</th></tr></thead><tbody><tr><td><strong>Is empty</strong></td><td>is blank or holds only spaces</td></tr><tr><td><strong>Is not empty</strong></td><td>holds anything</td></tr><tr><td><strong>Text contains</strong></td><td>contains the text you type, ignoring case</td></tr><tr><td><strong>Greater than</strong></td><td>is a number greater than the value</td></tr><tr><td><strong>Is between</strong></td><td>is a number from <strong>Min</strong> to <strong>Max</strong>, inclusive</td></tr><tr><td><strong>Date before</strong></td><td>is a date earlier than the date you type</td></tr><tr><td><strong>Date after</strong></td><td>is a date later than the date you type</td></tr></tbody></table><p>Number conditions ignore thousands separators. Type dates as <code>YYYY-MM-DD</code>. A cell that isn&#39;t a number or a date never matches those conditions.</p><h2 id="apply-a-rule-to-several-ranges" tabindex="-1">Apply a rule to several ranges <a class="header-anchor" href="#apply-a-rule-to-several-ranges" aria-label="Permalink to &quot;Apply a rule to several ranges&quot;">​</a></h2><ol><li>Select the rule&#39;s card in the panel.</li><li>Under <strong>Apply to range</strong>, type the ranges separated by commas, for example <code>A1:B10, D1:E10</code>.</li><li>Click <strong>Apply</strong>.</li></ol><p>Write both ends of every range. A single cell is <code>A1:A1</code>; a bare <code>A1</code> shows <code>Enter valid A1 ranges like A1:D20 or A1:B10, D1:E10.</code></p><p>To use the cells you have selected instead, click <strong>Use selected range</strong>. It needs a cell range; with a whole row or column selected it shows <code>Select a cell range first.</code></p><h2 id="change-the-rule-order" tabindex="-1">Change the rule order <a class="header-anchor" href="#change-the-rule-order" aria-label="Permalink to &quot;Change the rule order&quot;">​</a></h2><p>The panel applies rules from top to bottom. Click the ↑ or ↓ arrow on a rule&#39;s card to move it.</p><p>When two rules match the same cell, both apply. For a property both rules set, such as the background color, the lower rule wins.</p><h2 id="edit-or-delete-a-rule" tabindex="-1">Edit or delete a rule <a class="header-anchor" href="#edit-or-delete-a-rule" aria-label="Permalink to &quot;Edit or delete a rule&quot;">​</a></h2><ol><li>Select a cell the rule covers and click <strong>Conditional formatting</strong>. The panel opens on that rule.</li><li>Change its range, condition, or style. Edits save as you make them.</li><li>To delete the rule, click <strong>✕</strong> on its card.</li></ol><p>Each card shows the condition, the ranges, and a style summary such as <code>B · Fill</code>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>A rule can&#39;t change number formats, borders, fonts, or alignment.</li><li>A rule with no style, or with an empty value box, isn&#39;t kept.</li><li>Clicking the grid closes the panel. Select the cells before you open it.</li><li>Conditional formatting isn&#39;t available on data source or lakehouse tabs. Copy the results into a sheet tab to format them.</li><li>On a pivot tab, a rule stays on the cells you gave it, so a pivot that changes shape after a refresh can leave it on the wrong cells.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/data-validation.html">Data validation</a> to add dropdowns and checkboxes.</li><li><a href="/docs/sheets/edit-and-format.html">Edit and format cells</a> to style cells by hand.</li><li><a href="/docs/sheets/pivot-tables.html">Pivot tables</a> to summarize data before you highlight it.</li></ul>',29)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
